#if UNITY_EDITOR
using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.SceneManagement;
namespace StarterAssets.CQCEditorTools {
[InitializeOnLoad] public static class ReduceThroneHall {
const string Request="Assets/Editor/CQC/ReduceThroneHall-7x.request.txt";static double next;static Transform[] groundIgnore=Array.Empty<Transform>();
static ReduceThroneHall(){EditorApplication.update+=Poll;}
static void Poll(){if(EditorApplication.timeSinceStartup<next)return;next=EditorApplication.timeSinceStartup+2;if(!File.Exists(Request)||EditorApplication.isCompiling||EditorApplication.isUpdating)return;if(EditorApplication.isPlaying){EditorApplication.ExitPlaymode();return;}if(EditorApplication.isPlayingOrWillChangePlaymode)return;Undo.IncrementCurrentGroup();int group=Undo.GetCurrentGroup();try{Apply();Undo.CollapseUndoOperations(group);AssetDatabase.DeleteAsset(Request);}catch(Exception e){Undo.RevertAllDownToGroup(group);File.WriteAllText("Logs/ThroneHallReduced7x-error.txt",e.ToString());Debug.LogException(e);AssetDatabase.MoveAsset(Request,Request+".failed");}}
static Vector3 Ground(Vector3 p){var hits=Physics.RaycastAll(p+Vector3.up*6,Vector3.down,30,~0,QueryTriggerInteraction.Ignore).Where(h=>h.normal.y>.7f&&!groundIgnore.Any(t=>t&&h.collider.transform.IsChildOf(t))).OrderBy(h=>h.distance).ToArray();if(hits.Length==0)throw new InvalidOperationException("Missing supported floor at "+p);p.y=hits[0].point.y+.06f;return p;}
static void Apply(){var active=SceneManager.GetActiveScene();var scene=SceneManager.GetSceneByPath(ChapelThroneDomain.ScenePath);bool opened=!scene.isLoaded;if(opened)scene=EditorSceneManager.OpenScene(ChapelThroneDomain.ScenePath,OpenSceneMode.Additive);
try{SceneManager.SetActiveScene(scene);var room=scene.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<ThroneDomainRoom>(true)).Single();var root=room.transform;if(root.Find("Hall Reduced by 7x")){File.WriteAllText("Logs/ThroneHallReduced7x-report.txt","Already reduced by 7x. No duplicate reduction applied.");return;}if(!room.Arrival||!room.ReturnDoor)throw new InvalidOperationException("Room arrival and exit must be configured first.");string backup="Assets/ForestExpansion/Backups/ThroneDomain-before-reduce-7x-"+DateTime.Now.ToString("yyyyMMdd-HHmmss")+".unity";if(!EditorSceneManager.SaveScene(scene,backup,true))throw new IOException("Backup failed.");
var children=root.Cast<Transform>().ToArray();var seat=children.First(t=>t.name=="Throne Seat");var queen=children.FirstOrDefault(t=>t.name.StartsWith("Queen Beside Throne"));var throne=children.Where(t=>t.name=="Throne Seat"||t.name=="Throne Back"||t.name=="Throne Arm"||t.name=="Throne Gold Post"||t.name=="Throne Crown"||t.name=="Velvet Seat"||t.name=="Velvet Back").ToArray();var seatPosition=seat.position;var origin=root.position;var oldSeatBase=seatPosition-Vector3.up*(seat.GetComponent<Renderer>().bounds.extents.y);var queenOffset=queen?queen.position-seatPosition:Vector3.zero;var positions=throne.Select(t=>t.position-seatPosition).ToArray();var scales=throne.Select(t=>t.localScale).ToArray();var queenScale=queen?queen.localScale:Vector3.one;
const float factor=1f/7f;var originalScale=root.localScale;groundIgnore=queen?throne.Concat(new[]{queen}).ToArray():throne;var before=BoundsOf(root);Undo.RecordObject(root,"Reduce throne hall by 7x");foreach(var child in children)Undo.RecordObject(child,"Fit expanded hall props");root.localScale*=factor;Physics.SyncTransforms();
// Keep the seat and queen human-sized while the architecture, dais and floor enlarge.
var desiredBase=origin+(oldSeatBase-origin)*factor;var surface=Ground(desiredBase+Vector3.up*1);var newSeat=new Vector3(origin.x+(seatPosition.x-origin.x)*factor,surface.y+seat.GetComponent<Renderer>().bounds.extents.y/factor,origin.z+(seatPosition.z-origin.z)*factor);
for(int i=0;i<throne.Length;i++){throne[i].localScale=scales[i]/factor;throne[i].position=newSeat+positions[i];}
if(queen){queen.localScale=queenScale/factor;var qp=newSeat+queenOffset;queen.position=Ground(qp);}
foreach(var light in root.GetComponentsInChildren<Light>()){Undo.RecordObject(light,"Light larger throne hall");light.range*=factor;light.intensity*=factor*factor;light.shadows=LightShadows.None;}
Physics.SyncTransforms();room.ReturnDoor.position=Ground(room.ReturnDoor.position);var inward=Vector3.ProjectOnPlane(room.ReturnDoor.forward,Vector3.up).normalized;room.Arrival.position=Ground(room.ReturnDoor.position+inward*3.2f);room.Arrival.rotation=room.ReturnDoor.rotation;
var cc=UnityEngine.Object.FindAnyObjectByType<StarterAssets.ThirdPersonController>()?.GetComponent<CharacterController>();float radius=cc?cc.radius:.3f,height=cc?cc.height:1.8f;foreach(var point in new[]{room.Arrival.position,room.ReturnDoor.position}){if(Physics.OverlapCapsule(point+Vector3.up*(radius+.12f),point+Vector3.up*(height-radius),radius*.95f,~0,QueryTriggerInteraction.Ignore).Any(c=>!cc||!c.transform.IsChildOf(cc.transform)))throw new InvalidOperationException("Reduced hall entrance point is blocked at "+point);}
var marker=new GameObject("Hall Reduced by 7x");marker.transform.SetParent(root,false);Undo.RegisterCreatedObjectUndo(marker,"Record hall size");var after=BoundsOf(root);if(Vector3.Distance(root.localScale,originalScale*factor)>.01f)throw new InvalidOperationException("Hall scale did not match a sevenfold reduction.");EditorSceneManager.MarkSceneDirty(scene);if(!EditorSceneManager.SaveScene(scene))throw new IOException("Could not save reduced throne hall.");File.WriteAllText("Logs/ThroneHallReduced7x-report.txt","PASS: Hall architecture and collision surfaces reduced to one-seventh of previous width, length and height (10/7 of original size). Queen and throne retain original physical size. Lights adjusted, shadows disabled. Arrival remains 3.2m inside exit, both supported and capsule-clear.\nFinal root scale: "+root.localScale+"\nBefore bounds: "+before.size+"\nAfter bounds: "+after.size+"\nArrival: "+room.Arrival.position+"\nExit: "+room.ReturnDoor.position+"\nQueen: "+(queen?queen.position.ToString():"No queen found")+"\nBackup: "+backup);
File.WriteAllText("Assets/Editor/CQC/TestChapelMap-v1.request.txt","Verify map travel after sevenfold hall reduction.");
}finally{groundIgnore=Array.Empty<Transform>();if(active.IsValid()&&active.isLoaded)SceneManager.SetActiveScene(active);if(opened)EditorSceneManager.CloseScene(scene,true);}}
static Bounds BoundsOf(Transform root){var rs=root.GetComponentsInChildren<Renderer>(true);var b=rs[0].bounds;foreach(var r in rs)b.Encapsulate(r.bounds);return b;}
}}
#endif
